-- ============================================================
-- MediTrack Pro  |  05_sample_data.sql
-- Demo logins (bcrypt hashed):   demo / demo1234     drsmith / doctor123
-- Dates are relative to NOW() so the dashboard always has fresh data.
-- Patient codes (P100001...) are generated by trigger trg_patients_bi.
-- ============================================================
USE meditrack;


SET @demo  = (SELECT doctor_id FROM doctors WHERE username = 'demo');
SET @smith = (SELECT doctor_id FROM doctors WHERE username = 'drsmith');

