VALUES (@demo, 'Aarav Sharma', '1978-03-14', 'Male', '+91 98765 43210', 'aarav.sharma@example.com', '12 Anna Nagar, Chennai', 'Type 2 diabetes since 2015. Appendectomy 2009.');
SET @pid = LAST_INSERT_ID();

